import "fmt"

func sum(nums []int, out chan int) {
	total := 0
	for _, n := range nums {
		total += n
	}
	out <- total
}

func main() {
	nums := []int{4, 8, 15, 16, 23, 42}
	mid := len(nums) / 2

	results := make(chan int)
	go sum(nums[:mid], results)
	go sum(nums[mid:], results)

	a := <-results
	b := <-results
	fmt.Println("total:", a+b)
}

