package main

import "fmt"

func minInt(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func minOf(nums []int, out chan int) {
	smallest := nums[0]
	for _, n := range nums[1:] {
		smallest = minInt(smallest, n)
	}
	out <- smallest
}

func main() {
	values := []int{31, 7, 19, 42, 3, 25, 11, 8}
	mid := len(values) / 2

	results := make(chan int)
	go minOf(values[:mid], results)
	go minOf(values[mid:], results)

	a := <-results
	b := <-results
	fmt.Printf("smallest: %d\n", minInt(a, b))
}

