package main

import (
	"fmt"
	"strconv"
	"strings"
)

func squares(n int) <-chan int {
	out := make(chan int)
	go func() {
		defer close(out)
		for i := 1; i <= n; i++ {
			out <- i * i
		}
	}()
	return out
}

func main() {
	var n int
	fmt.Scan(&n)

	ch := squares(n)
	var parts []string
	for v := range ch {
		parts = append(parts, strconv.Itoa(v))
	}
	fmt.Println(strings.Join(parts, " "))

	v, ok := <-ch
	fmt.Println(v, ok)
}

