package main

import (
	"fmt"
	"strconv"
	"strings"
)

func fibBelow(limit int) <-chan int {
	out := make(chan int)
	go func() {
		defer close(out)
		a, b := 0, 1
		for a < limit {
			out <- a
			a, b = b, a+b
		}
	}()
	return out
}

func main() {
	var limit int
	fmt.Scan(&limit)

	ch := fibBelow(limit)
	var parts []string
	for v := range ch {
		parts = append(parts, strconv.Itoa(v))
	}
	fmt.Println(strings.Join(parts, " "))

	v, ok := <-ch
	fmt.Println(v, ok)
}

